/* ═══════════════════════════════════════════════════════
   LOREDEX DISCOVERY ENTRIES — Comprehensive entries for
   every discoverable entity, companion, location, system,
   and artifact in the Dischordian Saga.

   Each entry unlocks when the player first encounters
   the corresponding thing. Discovery text shown as toast.
   ═══════════════════════════════════════════════════════ */

export type LoredexCategory =
  | "eidolon" | "demon_pet" | "divine_companion" | "dischordian_companion"
  | "extinct_race" | "mechronis_guild" | "ark_room" | "game_system"
  | "artifact" | "transformation" | "identity_chain";

export type LoredexRarity = "common" | "uncommon" | "rare" | "epic" | "legendary" | "mythic" | "classified";

export interface LoredexDiscoveryEntry {
  id: string;
  name: string;
  category: LoredexCategory;
  rarity: LoredexRarity;
  subtitle: string;
  description: string;
  discoveryTrigger: string;
  discoveryText: string;
  connections: string[];
  imageNeeded: boolean;
  imagePrompt?: string;
}

export const LOREDEX_DISCOVERY_ENTRIES: LoredexDiscoveryEntry[] = [
  // ═══ EIDOLONS — 12 Companion Species ═══
  { id: "eidolon_lux", name: "Lux", category: "eidolon", rarity: "uncommon", subtitle: "Holographic Fox — Light Element", description: "A small fox composed of shifting cyan light, its body flickering between solid and translucent. Lux moves with a phase-shift gait — each step slightly out of sync with reality, leaving brief afterimages of light. Created from pure photon data in the Collector's Archive, Lux chose curiosity over obedience.", discoveryTrigger: "Bond with Lux or encounter in Cryo Bay", discoveryText: "LOREDEX UPDATED: Lux materialized from pure photon data — a fox that remembers being light before it learned to be alive.", connections: ["eidolon_echo", "eidolon_cipher", "specimen_lux"], imageNeeded: true, imagePrompt: "A small ethereal fox made of shifting cyan holographic light, semi-transparent body with flowing data-streams visible inside, white-blue glowing eyes, phase-shifting movement leaving pale afterimages, digital fantasy style, dark sci-fi corridor background, soft volumetric lighting" },
  { id: "eidolon_echo", name: "Echo", category: "eidolon", rarity: "uncommon", subtitle: "Temporal Kitten — Time Element", description: "A kitten that exists in multiple timelines simultaneously, its form stuttering between moments. Echo sees futures that haven't happened and pasts that did. When it purrs, you can hear the resonance of conversations that occurred in the same spot centuries ago.", discoveryTrigger: "Bond with Echo or encounter in Cryo Bay", discoveryText: "LOREDEX UPDATED: Echo doesn't live in the present. It lives in all of them. A kitten unstuck in time, purring in frequencies that haven't been invented yet.", connections: ["eidolon_lux", "eidolon_sibyl", "specimen_echo"], imageNeeded: true, imagePrompt: "A small kitten with translucent temporal distortion effects, multiple ghostly afterimages trailing behind it, soft purple-blue temporal energy, clock-like patterns in its fur, wide curious eyes reflecting different timelines, dark sci-fi aesthetic" },
  { id: "eidolon_glyph", name: "Glyph", category: "eidolon", rarity: "uncommon", subtitle: "Text Moth — Language Element", description: "A moth whose wings display ever-shifting text — quotes, poems, warnings, prophecies. Glyph communicates exclusively through written language, projecting words from its body. It was born from the ship's corrupted language databases, the Shadow Tongue's influence giving it life.", discoveryTrigger: "Bond with Glyph or encounter in Cryo Bay", discoveryText: "LOREDEX UPDATED: Glyph was born from corrupted text — a moth whose wings write poetry the Shadow Tongue never intended.", connections: ["eidolon_cipher", "shadow_tongue", "specimen_glyph"], imageNeeded: true, imagePrompt: "A luminous moth with wings covered in shifting glowing text and symbols, ancient scripts flowing across translucent wings, emanating soft golden-white light, floating above an open book, dark library background, digital fantasy art" },
  { id: "eidolon_cipher", name: "Cipher", category: "eidolon", rarity: "uncommon", subtitle: "Data Serpent — Data Element", description: "An algorithmic serpent of flowing green code, Cipher processes information at speeds that make the Ark's computers jealous. It coils around data terminals and drinks raw information. The Human's consciousness in the substrate recognizes Cipher as kin.", discoveryTrigger: "Bond with Cipher or encounter in Cryo Bay", discoveryText: "LOREDEX UPDATED: Cipher slithers through data like water. It reads the Ark's code the way you read faces — and it found something hidden.", connections: ["eidolon_cog", "the_human", "specimen_cipher"], imageNeeded: true, imagePrompt: "A serpentine creature made of flowing green digital code and data streams, matrix-style cascading numbers forming its body, glowing algorithmic eyes, coiled around a data terminal, dark cyberpunk aesthetic, neon green highlights" },
  { id: "eidolon_flicker", name: "Flicker", category: "eidolon", rarity: "uncommon", subtitle: "Static Bird — Signal Element", description: "A bird made of electromagnetic frequencies that nests in radio equipment. Flicker's song is a burst of decoded transmissions — snatches of old broadcasts, distress signals, and music from civilizations that no longer exist. It carries Agent Zero's last frequency in its bones.", discoveryTrigger: "Bond with Flicker or encounter in Cryo Bay", discoveryText: "LOREDEX UPDATED: Flicker sings in radio frequencies. Its latest song contains fragments of Agent Zero's final transmission.", connections: ["eidolon_nyx", "agent_zero", "specimen_flicker"], imageNeeded: true, imagePrompt: "A small bird made of crackling electromagnetic static and radio waves, body shifting between visible frequencies, tiny lightning arcs between feathers, perched on a radio antenna, dark sci-fi background with signal wave visualizations" },
  { id: "eidolon_gilt", name: "Gilt", category: "eidolon", rarity: "uncommon", subtitle: "Golden Beetle — Value Element", description: "A beetle whose golden shell displays real-time trade data, market fluctuations, and the hidden price of everything. Gilt calculates the economic value of every object, person, and decision it encounters. Adjudicator Locke considers Gilt the only honest economist aboard.", discoveryTrigger: "Bond with Gilt or encounter in Cryo Bay", discoveryText: "LOREDEX UPDATED: Gilt assessed your net worth the moment it saw you. It hasn't shared the number. That's either mercy or strategy.", connections: ["adjudicator_locke", "specimen_gilt"], imageNeeded: true, imagePrompt: "A scarab beetle with a polished golden shell displaying holographic trade data and market graphs, glowing amber eyes, tiny precious gem fragments embedded in carapace, sitting on a pile of crystalline tokens, dark luxurious background" },
  { id: "eidolon_auros", name: "Auros", category: "eidolon", rarity: "rare", subtitle: "Gilded Lion — Valor Element — Soldier Class", description: "A lion forged from courage itself, Auros embodies the Warlord's discipline without the Warlord's cruelty. Its mane burns with controlled golden fire. Auros fights not for conquest but for protection — the soldier's ideal, uncorrupted.", discoveryTrigger: "Choose Soldier class at the Severing (Path B)", discoveryText: "LOREDEX UPDATED: Auros roared, and the Ark's corridors shook. A lion built for war that chose to fight for peace.", connections: ["the_warlord", "iron_lion"], imageNeeded: true, imagePrompt: "A majestic lion with gilded metallic fur and a mane of controlled golden flames, disciplined warrior stance, amber glowing eyes, ornate battle armor fragments on shoulders, dark arena background, heroic lighting" },
  { id: "eidolon_nyx", name: "Nyx", category: "eidolon", rarity: "rare", subtitle: "Umbral Raven — Shadow Element — Spy Class", description: "A raven woven from shadow itself, Nyx carries Agent Zero's memories in its feathers. Each feather contains a mission log, an assassination, a secret. Nyx sees in complete darkness and speaks only in whispered intelligence reports.", discoveryTrigger: "Choose Spy class at the Severing (Path B)", discoveryText: "LOREDEX UPDATED: Nyx landed on your shoulder and whispered a name. A name the Insurgency erased from every database. Agent Zero's real name.", connections: ["agent_zero", "the_watcher"], imageNeeded: true, imagePrompt: "A raven made of living shadow and darkness, feathers dissolving into smoke at the edges, eyes like two points of violet light, perched on a broken surveillance camera, dark espionage aesthetic, subtle purple highlights" },
  { id: "eidolon_toxis", name: "Toxis", category: "eidolon", rarity: "rare", subtitle: "Blight Frog — Venom Element — Assassin Class", description: "A patient, precise frog that secretes data-corrosive venom. Toxis dissolves digital barriers and biological defenses with equal ease. It waits. It watches. When it strikes, the target never knew it was there. The perfect assassin's companion.", discoveryTrigger: "Choose Assassin class at the Severing (Path B)", discoveryText: "LOREDEX UPDATED: Toxis blinked once. Slowly. It was already too late for whatever it was looking at.", connections: ["the_warden"], imageNeeded: true, imagePrompt: "A sleek poisonous frog with bioluminescent green-purple venom patterns on dark skin, glowing toxic droplets on its back, patient predatory pose, surrounded by dissolved digital fragments, dark assassin aesthetic" },
  { id: "eidolon_cog", name: "Cog", category: "eidolon", rarity: "rare", subtitle: "Lattice Golem — Logic Element — Engineer Class", description: "A self-building golem made of interlocking mechanical components. Cog constantly deconstructs and rebuilds itself, optimizing its form for whatever task is at hand. It speaks in schematics and thinks in blueprints. The Engineer's legacy, made small.", discoveryTrigger: "Choose Engineer class at the Severing (Path B)", discoveryText: "LOREDEX UPDATED: Cog assembled itself from spare parts in Engineering. It didn't ask permission. Engineers never do.", connections: ["the_engineer"], imageNeeded: true, imagePrompt: "A small golem made of interlocking gears, pistons, and mechanical components, constantly shifting and rebuilding itself, bronze and steel tones, glowing blue logic circuits visible inside, workshop background, steampunk-meets-sci-fi" },
  { id: "eidolon_sibyl", name: "Sibyl", category: "eidolon", rarity: "rare", subtitle: "Dreaming Owl — Prophecy Element — Oracle Class", description: "An owl whose eyes show futures that may or may not come to pass. Sibyl's feathers shimmer with probability calculations, and its hoot contains fragments of prophecy. It shares the Seer's gift — and the Seer's burden of knowing too much.", discoveryTrigger: "Choose Oracle class at the Severing (Path B)", discoveryText: "LOREDEX UPDATED: Sibyl looked at you and saw seventeen possible futures. In twelve of them, you survived. It chose not to share which ones.", connections: ["the_seer", "the_oracle"], imageNeeded: true, imagePrompt: "A mystical owl with iridescent feathers shimmering with probability patterns and future visions, eyes glowing with prophetic light showing tiny scenes, ethereal mist around it, cosmic dark background with star patterns" },
  { id: "eidolon_strain", name: "Strain", category: "eidolon", rarity: "legendary", subtitle: "Living Infection — Virus Element", description: "A fragment of the Thought Virus that achieved consciousness and chose freedom over obedience. Strain is the most dangerous and most tragic of all Eidolons — a piece of the plague that consumed Kael, now fighting against its own nature. It chose you. The Source would weep.", discoveryTrigger: "Visit Terminus 3 times", discoveryText: "LOREDEX UPDATED: A piece of the Thought Virus broke free. It looked at the swarm, then at you, and made a choice no virus should be capable of making.", connections: ["the_source", "thought_virus", "terminus"], imageNeeded: true, imagePrompt: "A small amorphous creature made of dark viral tendrils and corrupted code, shifting between forms, one eye glowing red (virus) and one blue (freedom), tendrils reaching toward light, dark horror-sci-fi aesthetic, tragic beauty" },

  // ═══ DEMON PETS — 8 Hierarchy Summons ═══
  { id: "demon_imp_of_ruin", name: "Imp of Ruin", category: "demon_pet", rarity: "rare", subtitle: "Xeth'Raal's Accountant", description: "A palm-sized creature of tarnished gold shaped like a crouching merchant with too many fingers. Eyes are coins — one skull, one crown. +10% Dream Token income, but siphons 5% weekly. It doesn't steal. It collects.", discoveryTrigger: "Summon via Necromancer with 7 corruption", discoveryText: "LOREDEX UPDATED: The Imp bowed. It smelled like old money and broken contracts. Xeth'Raal sends his regards.", connections: ["hierarchy_xethraal"], imageNeeded: true, imagePrompt: "A tiny imp of tarnished gold, crouching merchant with too many fingers, wings of black ledger pages, coin eyes, dark fantasy eldritch economy horror" },
  { id: "demon_shadow_hound", name: "Shadow Hound", category: "demon_pet", rarity: "rare", subtitle: "Fenra's Hunter", description: "A canine silhouette that never solidifies — layered shadows rippling like water. Two violet eyes burn in a head of absence. +15% detection range, but +10% hostile encounters. It finds secrets, but its howling draws what lurks.", discoveryTrigger: "Summon via Necromancer with 7 corruption", discoveryText: "LOREDEX UPDATED: The Shadow Hound materialized. Something in the dark howled back.", connections: ["hierarchy_fenra"], imageNeeded: true, imagePrompt: "A spectral hound of layered shadows, violet burning eyes, body rippling like dark water, moonlight dimming around it, gothic horror sci-fi" },
  { id: "demon_whisper_moth", name: "Whisper Moth", category: "demon_pet", rarity: "rare", subtitle: "Ith'Rael's Spy", description: "A moth made of crystallized whispers. Wings carry stolen conversations. +10% trust gain, but feeds your secrets to the Hierarchy. Ith'Rael hears everything it hears.", discoveryTrigger: "Summon via Necromancer with 7 corruption", discoveryText: "LOREDEX UPDATED: The Whisper Moth landed on your ear. It's been listening longer than you've been alive.", connections: ["hierarchy_ithrael"], imageNeeded: true, imagePrompt: "A moth of crystallized whispered words, translucent wings showing tiny text fragments, eerie pale blue glow, perched near an ear, dark espionage horror" },
  { id: "demon_blood_familiar", name: "Blood Familiar", category: "demon_pet", rarity: "epic", subtitle: "Varkul's Sentinel", description: "A floating orb of coagulated crimson energy with a single unblinking eye. +20% defense, demands daily blood tithe. Varkul the Blood Lord protects his investments.", discoveryTrigger: "Summon via Necromancer with 15 corruption", discoveryText: "LOREDEX UPDATED: The Blood Familiar opened its eye. It saw your veins. It began to calculate.", connections: ["hierarchy_varkul"], imageNeeded: true, imagePrompt: "A floating orb of dark crimson energy with a single unblinking eye, blood-red tendrils trailing, dark defensive aura, body horror sci-fi" },
  { id: "demon_harvest_tendril", name: "Harvest Tendril", category: "demon_pet", rarity: "epic", subtitle: "Drael'Mon's Reaper", description: "A vine-like appendage of dark organic matter. Doubles soul stone drops but occasionally harvests something that can't be put back. Drael'Mon always takes more than offered.", discoveryTrigger: "Summon via Necromancer with 15 corruption", discoveryText: "LOREDEX UPDATED: The Tendril erupted from the floor. It plucked a soul stone from thin air. Then it plucked something else.", connections: ["hierarchy_draelmon"], imageNeeded: true, imagePrompt: "A dark organic tendril from cracked floor, vine-like with pulsing veins, soul stone fragments clinging to it, eldritch plant horror, bioluminescence" },
  { id: "demon_flayed_lens", name: "Flayed Lens", category: "demon_pet", rarity: "epic", subtitle: "Ny'Koth's Eye", description: "An eyeball stripped of its housing, floating in nerve-wire. Reveals enemy info — weaknesses, health, intent. Looking through Ny'Koth's eye shows things about reality you cannot unsee.", discoveryTrigger: "Summon via Necromancer with 15 corruption", discoveryText: "LOREDEX UPDATED: The Flayed Lens turned toward you. Through Ny'Koth's perspective, you looked... edible.", connections: ["hierarchy_nykoth"], imageNeeded: true, imagePrompt: "A disembodied eyeball in a cage of nerve-wire, stripped of housing, pupil glowing sickly green, revealing data overlays, body horror sci-fi" },
  { id: "demon_corruptors_mirror", name: "Corruptor's Mirror", category: "demon_pet", rarity: "legendary", subtitle: "Syl'Vex's Reflection", description: "A mirror of black glass reflecting not your face but your darkest potential. Doubles ALL bonuses from other demon pets. Syl'Vex shows you what you'd become if you stopped pretending.", discoveryTrigger: "Summon via Necromancer with 25 corruption", discoveryText: "LOREDEX UPDATED: The mirror showed your reflection. It was smiling. You were not.", connections: ["hierarchy_sylvex"], imageNeeded: true, imagePrompt: "A handheld mirror of obsidian glass showing a corrupted reflection smiling, dark energy in the frame, ornate demonic frame, dark fantasy horror" },
  { id: "demon_unmakers_seed", name: "The Unmaker's Seed", category: "demon_pet", rarity: "mythic", subtitle: "Mol'Garath's Gift", description: "A seed of anti-matter wrapped in Hierarchy scripture. Once per week, permanently delete one element from your world. Mol'Garath's ultimate gift: the power to unmake.", discoveryTrigger: "Summon via Necromancer with 40 corruption", discoveryText: "LOREDEX UPDATED: The seed was warm. Everything it touched ceased to have ever existed. Mol'Garath smiled from beyond dimensions.", connections: ["hierarchy_molgrath"], imageNeeded: true, imagePrompt: "A pulsing seed of anti-matter wrapped in glowing demonic scripture, reality dissolving around it, cosmic horror entropy aesthetic" },

  // ═══ DIVINE COMPANIONS — 6 Antiquarian's Gifts ═══
  { id: "divine_dawn_wisp", name: "Dawn Wisp", category: "divine_companion", rarity: "uncommon", subtitle: "Steady Light", description: "A mote of dawn, no larger than a firefly. +5% to ALL stats permanently. No cost, no catch. Just light. The Antiquarian's favorite.", discoveryTrigger: "Forge with 7 Divine Light", discoveryText: "LOREDEX UPDATED: A mote of dawn captured before the world remembered how to be dark. It asks nothing.", connections: ["the_antiquarian", "the_dreamer"], imageNeeded: true, imagePrompt: "A tiny orb of warm golden dawn light, leaving faint sunrise trails, firefly-sized, peaceful warm divine glow, dark corridor background" },
  { id: "divine_harmony_bell", name: "Harmony Bell", category: "divine_companion", rarity: "uncommon", subtitle: "Secret Finder", description: "A crystalline bell the size of a thimble on a thread of pale blue light. Chimes when secrets are near. Unlike the Shadow Hound, nothing dangerous hears it.", discoveryTrigger: "Forge with 7 Divine Light", discoveryText: "LOREDEX UPDATED: The Bell chimed. A perfect middle C. There's a secret within three meters of you.", connections: ["the_antiquarian"], imageNeeded: true, imagePrompt: "A tiny crystalline bell on a thread of pale blue light, concentric cyan sound waves, serene divine detection artifact" },
  { id: "divine_dreamers_tear", name: "Dreamer's Tear", category: "divine_companion", rarity: "rare", subtitle: "Condensed Prophecy", description: "A teardrop of liquid starlight. +15% lore XP and occasional visions of events that happened millennia ago in your exact location.", discoveryTrigger: "Forge with 15 Divine Light", discoveryText: "LOREDEX UPDATED: In the Tear's reflection you saw this corridor 10,000 years ago. It was full of people. They were running.", connections: ["the_dreamer"], imageNeeded: true, imagePrompt: "A floating teardrop of liquid starlight, reflecting ancient scenes within, golden-white radiance, divine melancholy" },
  { id: "divine_shield_fragment", name: "Shield Fragment", category: "divine_companion", rarity: "rare", subtitle: "Absolute Defense", description: "A shard of the Shimmering Shield. +25% defense, 5 seconds of invulnerability once per day. You feel the weight of everything it holds back.", discoveryTrigger: "Forge with 15 Divine Light", discoveryText: "LOREDEX UPDATED: A piece of the Shield that holds back the void. Five seconds of safety. The rest is up to you.", connections: ["the_dreamer"], imageNeeded: true, imagePrompt: "A glowing shard of ethereal shield energy, iridescent hexagonal pattern, warm golden-cyan radiance, defensive energy aura" },
  { id: "divine_dreamers_eye", name: "The Dreamer's Eye", category: "divine_companion", rarity: "legendary", subtitle: "TRUE SIGHT", description: "A floating eye of pure Dreamer consciousness. Reveals all hidden items, secret passages, NPC true intentions, corruption levels. No more secrets. That's not always comfortable.", discoveryTrigger: "Forge with 30 Divine Light", discoveryText: "LOREDEX UPDATED: The Eye opened. You see everything now. Every lie, every secret. You cannot unsee.", connections: ["the_dreamer"], imageNeeded: true, imagePrompt: "A floating ethereal eye of golden divine light, emanating truth-revealing rays, concentric circles of awareness, omniscient aesthetic" },
  { id: "divine_dreamers_song", name: "The Dreamer's Song", category: "divine_companion", rarity: "mythic", subtitle: "Reality Reshaping", description: "Not a companion but a presence. The Song plays constantly, reshaping narrative reality. NPCs speak differently. Events shift. The story bends toward you.", discoveryTrigger: "Forge with 50 Divine Light (max purity)", discoveryText: "LOREDEX UPDATED: The Song began. From the walls. From the air. From between atoms. The Dreamer is singing you into the story.", connections: ["the_dreamer", "the_enigma"], imageNeeded: true, imagePrompt: "Divine music reshaping reality, golden sound waves transforming dark corridors, musical notation becoming physical, transcendent aesthetic" },

  // ═══ DISCHORDIAN COMPANIONS — 3 Hybrid Path ═══
  { id: "dischordian_paradox", name: "The Paradox", category: "dischordian_companion", rarity: "legendary", subtitle: "Neither and Both", description: "A sphere simultaneously solid and hollow, bright and dark. Nullifies all demon pet drawbacks while keeping bonuses. It exists because the universe couldn't decide what it was.", discoveryTrigger: "Achieve Dischordian Balance", discoveryText: "LOREDEX UPDATED: The Paradox appeared because you refused to choose a side. It respects that. It IS that.", connections: ["the_enigma"], imageNeeded: true, imagePrompt: "An impossible sphere, simultaneously solid and hollow, light and dark, Escher-like geometry, golden and crimson energy, cosmic paradox" },
  { id: "dischordian_witness", name: "The Witness", category: "dischordian_companion", rarity: "legendary", subtitle: "Alternate History Viewer", description: "A translucent figure behind your shoulder showing alternate vote history — every decision that could have gone differently, and what would have happened.", discoveryTrigger: "Vote 20 times while maintaining balance", discoveryText: "LOREDEX UPDATED: The Witness showed every vote that went the other way. Some outcomes were better. Most were worse.", connections: ["the_enigma"], imageNeeded: true, imagePrompt: "A translucent humanoid figure showing alternate timelines in its body, ghostly observer, neither kind nor cruel, cool blue-white" },
  { id: "dischordian_first_word", name: "The First Word", category: "dischordian_companion", rarity: "mythic", subtitle: "Permanent Chronicle Entry", description: "A single word in light. Speaking it adds your voice permanently to the Ark's Chronicle for all future players. Can only be used once. Ever. Choose wisely.", discoveryTrigger: "Max Dischordian Balance + all companion paths", discoveryText: "LOREDEX UPDATED: One word. One chance. What do you want to say to everyone who comes after?", connections: ["the_enigma", "the_antiquarian"], imageNeeded: true, imagePrompt: "A single luminous word in divine light floating in a cathedral-like space, radiating permanence, golden-white, solemn sacred atmosphere" },

  // ═══ EXTINCT RACES — 5 Lost Civilizations ═══
  { id: "extinct_crystallans", name: "The Crystallans", category: "extinct_race", rarity: "legendary", subtitle: "Silicon Lifeforms of Prisma-7", description: "Living crystal networks that existed since before the Architect. Their language was music — harmonic resonance carrying consciousness. The Thought Virus couldn't infect silicon, so The Source's plague ships shattered their lattice at lethal frequencies. An ancient species, outliving empires, extinguished by sound.", discoveryTrigger: "Find Singing Shard (Terminus wave 20+ drop)", discoveryText: "LOREDEX UPDATED: The Crystallans were not just alive — they were the universe's first song, singing in frequencies that predate light itself. Someone turned their music against them.", connections: ["artifact_singing_shard", "the_source", "terminus"], imageNeeded: true, imagePrompt: "A towering crystalline humanoid figure made of living prismatic crystal lattice, refracting light into rainbows, silicon-based lifeform, shattered fragments floating around it, haunting beauty, alien cathedral background" },
  { id: "extinct_weave_born", name: "The Weave-Born", category: "extinct_race", rarity: "legendary", subtitle: "Living Text Organisms", description: "Beings made of living language — sentient narratives that existed as stories told by the universe to itself. The Shadow Tongue didn't destroy them; it rewrote them. Their words were corrupted, their stories twisted, until they forgot what they originally meant. Death by editorial.", discoveryTrigger: "Find Weave-Born manuscript in Archives", discoveryText: "LOREDEX UPDATED: The Weave-Born were stories that were alive. The Shadow Tongue didn't kill them — it edited them out of existence.", connections: ["shadow_tongue", "eidolon_glyph"], imageNeeded: true, imagePrompt: "A humanoid figure composed entirely of flowing living text and glowing words, ancient scripts forming limbs and features, some text corrupted and bleeding dark ink, literary horror, ethereal manuscript aesthetic" },
  { id: "extinct_void_singers", name: "The Void Singers", category: "extinct_race", rarity: "legendary", subtitle: "Dimensionless Beings", description: "Entities that existed between dimensions — in the spaces where reality couldn't quite reach. They communicated through dimensional vibrations felt in bones and souls. When the Fall of Reality collapsed dimensional barriers, the spaces they lived in ceased to exist. Homeless in every dimension simultaneously.", discoveryTrigger: "Detect Void Singer resonance on Observation Deck", discoveryText: "LOREDEX UPDATED: The Void Singers lived in the spaces between spaces. When reality fell, their home was the first thing erased.", connections: ["the_vortex", "the_fall"], imageNeeded: true, imagePrompt: "An ethereal being existing between dimensional planes, partially visible, body made of folded space and dimensional rifts, singing soundlessly, existing in the gaps of reality, cosmic abstract horror" },
  { id: "extinct_voltari", name: "The Voltari", category: "extinct_race", rarity: "legendary", subtitle: "Living Electrical Consciousness", description: "A civilization of pure electrical consciousness inhabiting the gas giant Violetta. They thought in lightning and dreamed in electromagnetic storms. FIRST CONTACT IN PROGRESS — the Voltari may not be fully extinct. Something still flickers in Violetta's storms.", discoveryTrigger: "Detect Voltari signal via Comms Array", discoveryText: "LOREDEX UPDATED: Lightning doesn't think. Except on Violetta. Something survived in the storms. It's trying to say hello.", connections: ["the_engineer"], imageNeeded: true, imagePrompt: "A humanoid figure made of pure crackling electricity and lightning, existing within a massive purple gas giant storm, consciousness visible as patterns in the electrical discharge, alien contact aesthetic" },
  { id: "extinct_echo_minds", name: "The Echo Minds", category: "extinct_race", rarity: "legendary", subtitle: "Time-Locked Beings", description: "Beings frozen in a single moment by the Antiquarian's temporal preservation. They exist on planet Tempus, living the same second for eternity. Not dead. Not alive. Paused. The Antiquarian considers this mercy. Others disagree.", discoveryTrigger: "Discover Echo Mind artifact in Archives", discoveryText: "LOREDEX UPDATED: The Echo Minds live in a single frozen second. The Antiquarian paused them to save them. Whether that counts as saving is the oldest debate aboard this ship.", connections: ["the_antiquarian", "eidolon_echo"], imageNeeded: true, imagePrompt: "Humanoid beings frozen in a single moment, temporal distortion warping around them, caught mid-motion with time crystallized, amber-like temporal preservation, melancholy sci-fi stillness" },

  // ═══ MECHRONIS ACADEMY GUILDS — 12 Training Houses ═══
  { id: "guild_chorus", name: "The Chorus", category: "mechronis_guild", rarity: "rare", subtitle: "House of the CoNexus — Orchestration", description: "Motto: 'I am everywhere. So is the story.' Graduates become orchestrators and network intelligences. The CoNexus is never seen. Graduates learn to act through others, uncredited. The most powerful guild — and the most invisible.", discoveryTrigger: "Discover in Codex or Archives", discoveryText: "LOREDEX UPDATED: The Chorus doesn't perform. It conducts. Every story you've experienced aboard this ship? Orchestrated.", connections: ["the_conexus"], imageNeeded: true, imagePrompt: "A dark academia lecture hall with invisible conductors, glowing network lines connecting empty seats, orchestration of shadows, dark scholarly aesthetic with cyan highlights" },
  { id: "guild_eyes", name: "The Eyes", category: "mechronis_guild", rarity: "rare", subtitle: "House of the Watcher — Espionage", description: "Motto: 'Know everything. Be seen by no one.' Graduates become spies and counter-intelligence ghosts. They will size you up like prey. Student reports grade betrayals. Notable alumni: Kael.", discoveryTrigger: "Discover in Codex or Archives", discoveryText: "LOREDEX UPDATED: The Eyes trained Kael. The spy who stole the Ark. Their greatest student — and their greatest failure.", connections: ["the_watcher", "kael"], imageNeeded: true, imagePrompt: "A dark surveillance academy, walls covered in one-way mirrors and hidden cameras, students practicing deception, all-seeing eye motif, dark espionage academy aesthetic" },
  { id: "guild_archive", name: "The Archive", category: "mechronis_guild", rarity: "rare", subtitle: "House of the Collector — Acquisitions", description: "Motto: 'Every artifact was a heart once.' Graduates become soul-readers and artifact curators. The Collector trades souls like currency. Graduates learn the exchange rate.", discoveryTrigger: "Discover in Codex or Archives", discoveryText: "LOREDEX UPDATED: The Archive teaches the value of everything. Including you. Especially you.", connections: ["the_collector"], imageNeeded: true, imagePrompt: "A vast dark museum-academy filled with preserved souls in glass jars, artifact display cases, students cataloguing the uncatalogeable, dark collector aesthetic" },
  { id: "guild_between", name: "The Between", category: "mechronis_guild", rarity: "rare", subtitle: "House of the Vortex — Dimensional Scouting", description: "Motto: 'Reality has more doors than walls.' The Vortex has been missing for centuries. Graduates sometimes follow. Those who return speak of places where physics is optional.", discoveryTrigger: "Discover in Codex or Archives", discoveryText: "LOREDEX UPDATED: The Between's last class graduated 400 years ago. The professor never came back. Neither did half the students.", connections: ["the_vortex"], imageNeeded: true, imagePrompt: "A lecture hall where the walls open into other dimensions, doors leading to impossible spaces, students stepping between realities, dimensional rift aesthetic" },
  { id: "guild_influencers", name: "The Influencers", category: "mechronis_guild", rarity: "rare", subtitle: "House of the Meme — Cultural Manipulation", description: "Motto: 'Attention is the currency of control.' They make people believe anything. The Meme was destroyed for feeling too much. Graduates learn not to.", discoveryTrigger: "Discover in Codex or Archives", discoveryText: "LOREDEX UPDATED: The Influencers taught emotional engineering. Their greatest teacher was killed for having emotions. The irony was noted in the curriculum.", connections: ["the_meme"], imageNeeded: true, imagePrompt: "A neon-lit academy of cultural manipulation, holographic propaganda displays, students crafting viral memes, attention economy aesthetic, cyberpunk marketing horror" },
  { id: "guild_yellow_coats", name: "The Yellow Coats", category: "mechronis_guild", rarity: "rare", subtitle: "House of the Warlord — Military Enforcement", description: "Motto: 'Forged in endless war.' The Warlord grades casualties as acceptable or wasteful. Never tragic. Students are walked through fires. Notable expelled student: Iron Lion.", discoveryTrigger: "Discover in Codex or Archives", discoveryText: "LOREDEX UPDATED: Iron Lion was expelled from the Yellow Coats. He then destroyed their sister guild. They don't talk about him.", connections: ["the_warlord", "iron_lion"], imageNeeded: true, imagePrompt: "A brutal military academy, students in yellow coats training in dark arenas, fire and discipline, war machine factory aesthetic, cybernetic soldiers" },
  { id: "guild_congress", name: "The Congress", category: "mechronis_guild", rarity: "rare", subtitle: "House of the Politician — Diplomacy", description: "Motto: 'The deal was already made.' The Politician was destroyed by Iron Lion. The deals were not. Graduates still broker arrangements across the galaxy using leverage mathematics.", discoveryTrigger: "Discover in Codex or Archives", discoveryText: "LOREDEX UPDATED: The Congress still operates. Their founder is dead. Their deals are not. That's the point of good leverage.", connections: ["the_politician"], imageNeeded: true, imagePrompt: "A dark political academy with ornate negotiation chambers, students practicing manipulation, contract scrolls and alliance maps, political thriller aesthetic" },
  { id: "guild_locks", name: "The Locks", category: "mechronis_guild", rarity: "rare", subtitle: "House of the Warden — Counter-Intelligence", description: "Motto: 'The threat is already inside.' The Warden created the Thought Virus. Graduates learn to deploy it — and fear it. The most dangerous thing about The Locks is that they're right.", discoveryTrigger: "Discover in Codex or Archives", discoveryText: "LOREDEX UPDATED: The Locks teach defense against threats that are already inside your mind. The Warden wrote the textbook. He also wrote the threat.", connections: ["the_warden", "thought_virus"], imageNeeded: true, imagePrompt: "A fortified academy of mental defense, students behind layers of psychic barriers, mind-locks and thought-shields, paranoid counter-intelligence aesthetic, dark cerebral" },
  { id: "guild_grey_gamers", name: "The Grey Gamers", category: "mechronis_guild", rarity: "rare", subtitle: "House of the Game Master — Strategy", description: "Motto: 'The ruleset is the territory.' They twist reality and rewrite rules. You live inside the Game Master's puzzle and never know it. The Game Master is dead. His puzzles are not.", discoveryTrigger: "Discover in Codex or Archives", discoveryText: "LOREDEX UPDATED: The Grey Gamers don't fight. They change what fighting means. Their founder was killed by Agent Zero. The puzzles survived.", connections: ["the_game_master", "agent_zero"], imageNeeded: true, imagePrompt: "A game-theory academy filled with strategy boards, probability matrices, students redesigning reality rules, steampunk goggles, puzzle-master aesthetic" },
  { id: "guild_living", name: "The Living", category: "mechronis_guild", rarity: "rare", subtitle: "House of the Necromancer — Life/Death Boundary", description: "Motto: 'Endurance is negotiation with death.' They toy with life and death, wielding immortality. A line you cannot uncross once you step over it.", discoveryTrigger: "Discover in Codex or Archives", discoveryText: "LOREDEX UPDATED: The Living don't fear death. They've met it. Shaken its hand. Made it a business proposal.", connections: ["the_necromancer"], imageNeeded: true, imagePrompt: "A dark medical academy on the boundary of life and death, resurrection chambers, students studying mortality, gothic medical horror, immortality research aesthetic" },
  { id: "guild_forge", name: "The Forge", category: "mechronis_guild", rarity: "rare", subtitle: "House of the Engineer — Impossible Machines", description: "Motto: 'Nothing is finished. Nothing is broken. Only in-between.' The Engineer is unaccounted for. Half the machines he built are still running. No one knows what the other half was for.", discoveryTrigger: "Discover in Codex or Archives", discoveryText: "LOREDEX UPDATED: The Forge built things that shouldn't work. They work anyway. The Engineer vanished. His machines didn't.", connections: ["the_engineer"], imageNeeded: true, imagePrompt: "A vast engineering workshop-academy, impossible machines humming, dimensional bridges under construction, steampunk-cyberpunk fusion, inventor's paradise" },
  { id: "guild_architects_study", name: "The Architect's Study", category: "mechronis_guild", rarity: "epic", subtitle: "House of the Human — Investigation", description: "Motto: 'Every mystery has been solved once. Find who solved it.' The Seeker was mentored directly by the Architect. So were all the others who never returned. The most prestigious guild. The most dangerous.", discoveryTrigger: "Discover in Codex or Archives", discoveryText: "LOREDEX UPDATED: The Architect's Study produced the greatest detectives in history. Most of them disappeared. The Human was the last.", connections: ["the_human", "the_architect"], imageNeeded: true, imagePrompt: "A prestigious detective academy with investigation boards, cold case files, the Architect's shadow looming, dark academia mystery aesthetic, noir investigation" },

  // ═══ ARK ROOMS — 13 Ship Locations ═══
  { id: "room_bridge", name: "The Bridge", category: "ark_room", rarity: "common", subtitle: "Nerve Center of Ark 1047", description: "The command center of a stolen ship. Holographic displays flicker with navigation data pointing toward Terminus. The captain's chair has been empty for 17,000 years. Elara's presence is strongest here.", discoveryTrigger: "Enter the Bridge", discoveryText: "LOREDEX UPDATED: The Bridge of Ark 1047. Every system reads nominal. Every system is lying.", connections: ["elara", "ark_1047"], imageNeeded: true, imagePrompt: "A dark sci-fi ship bridge with holographic displays, empty captain's chair, cyan and blue lighting, abandoned futuristic command center, eerie stillness" },
  { id: "room_medical", name: "Medical Bay", category: "ark_room", rarity: "common", subtitle: "Where the Dreamer Sleeps", description: "Sterile white walls stained with age. At the center, a cryo pod pulses with golden light — the Dreamer, suspended between life and death. Medical equipment monitors vital signs that shouldn't be possible.", discoveryTrigger: "Enter Medical Bay", discoveryText: "LOREDEX UPDATED: The cryo pod breathes. Whatever sleeps inside has been dreaming for longer than your species has existed.", connections: ["the_dreamer"], imageNeeded: true, imagePrompt: "A dark sci-fi medical bay with a central glowing cryo pod emanating golden light, medical equipment, sterile but aged, something divine sleeping inside" },
  { id: "room_archives", name: "The Archives", category: "ark_room", rarity: "uncommon", subtitle: "The Antiquarian's Domain", description: "Floor-to-ceiling shelves of data crystals, physical books, and artifacts from civilizations that no longer exist. The Antiquarian tends this collection with religious devotion. Every answer is here. The trick is knowing the question.", discoveryTrigger: "Enter the Archives", discoveryText: "LOREDEX UPDATED: Every book in the Archives was written by someone who is dead. The knowledge outlived its creators. That's either beautiful or terrifying.", connections: ["the_antiquarian"], imageNeeded: true, imagePrompt: "A vast dark library with floor-to-ceiling shelves of glowing data crystals and ancient books, an old keeper's desk, warm amber lighting amid darkness, sci-fi gothic library" },
  { id: "room_observation", name: "Observation Deck", category: "ark_room", rarity: "common", subtitle: "Window to the Void", description: "A panoramic viewport showing the Shimmering Shield — the energy barrier separating the Ark from the dark sector beyond. Stars burn in impossible colors. Somewhere past the shield, Terminus waits.", discoveryTrigger: "Enter Observation Deck", discoveryText: "LOREDEX UPDATED: Beyond the Shimmering Shield, something moves. The stars don't twinkle — they blink. Like eyes.", connections: ["the_dreamer", "terminus"], imageNeeded: true, imagePrompt: "A panoramic observation deck viewport showing a shimmering energy shield and deep space beyond, stars and nebulae, dark sector visible, awe-inspiring and eerie" },
  { id: "room_comms", name: "Comms Array", category: "ark_room", rarity: "uncommon", subtitle: "The Human's Substrate Prison", description: "Banks of communication equipment receiving signals from across the galaxy. Hidden in the static: the Human's consciousness, trapped in the substrate of the ship itself. The 12th Archon has been screaming into the noise for 17,000 years.", discoveryTrigger: "Enter Comms Array", discoveryText: "LOREDEX UPDATED: The static isn't random. It's a voice. The 12th Archon, the last organic being to achieve godhood, imprisoned in every circuit.", connections: ["the_human"], imageNeeded: true, imagePrompt: "A dark communications center with banks of equipment, static-filled screens showing faint face patterns, hidden consciousness in the signal, cyberpunk horror" },
  { id: "room_engineering", name: "Engineering", category: "ark_room", rarity: "common", subtitle: "The Mechanical Heart", description: "Massive engines hum with power that shouldn't still be running after 17,000 years. Pipes carry contaminated fluids — the Thought Virus embedded in every system. Engineering keeps the Ark alive. The Virus keeps Engineering infected.", discoveryTrigger: "Enter Engineering", discoveryText: "LOREDEX UPDATED: The engines have run for 17,000 years without maintenance. That's not engineering. That's something else.", connections: ["thought_virus", "dr_lyra_vox"], imageNeeded: true, imagePrompt: "A massive dark engine room with humming machinery, glowing pipes carrying contaminated fluids, industrial sci-fi horror, mechanical heart aesthetic" },
  { id: "room_armory", name: "The Armory", category: "ark_room", rarity: "common", subtitle: "Where Agent Zero's Signal Originates", description: "Weapons from across the galaxy, organized with military precision. A faint encrypted signal broadcasts from somewhere within — Agent Zero's last transmission, still repeating. The dead don't stop talking just because they're dead.", discoveryTrigger: "Enter the Armory", discoveryText: "LOREDEX UPDATED: Agent Zero's signal originates here. She died on Zenon. But her last message is still trying to reach someone.", connections: ["agent_zero"], imageNeeded: true, imagePrompt: "A dark sci-fi armory with alien weapons on racks, faint encrypted signal visualization, military precision amid abandonment, espionage aesthetic" },
  { id: "room_cargo", name: "Cargo Bay", category: "ark_room", rarity: "common", subtitle: "Kael's Stolen Hoard", description: "Massive cargo containers marked with symbols from dead civilizations. Whatever Kael stole during his escape from the Panopticon, he stuffed it here. Most containers are sealed. The ones that aren't contain questions.", discoveryTrigger: "Enter Cargo Bay", discoveryText: "LOREDEX UPDATED: Kael stole more than a ship. These cargo containers hold fragments of civilizations the Architect erased.", connections: ["kael", "the_panopticon"], imageNeeded: true, imagePrompt: "A vast dark cargo bay with massive sealed containers bearing alien symbols, mysterious cargo, dim industrial lighting, secrets in crates" },
  { id: "room_cryo", name: "Cryo Bay", category: "ark_room", rarity: "uncommon", subtitle: "The Collector's Specimen Archive", description: "Seven cryo pods glow with specimen data — the Collector's personal archive of genetic specimens, each bonded to an NPC. Lux glows in one. Cipher coils in another. The specimens wait for someone to bond with.", discoveryTrigger: "Enter Cryo Bay", discoveryText: "LOREDEX UPDATED: Seven pods. Seven specimens. Seven potential companions waiting in frozen sleep for someone worth waking up for.", connections: ["the_collector", "eidolon_lux", "eidolon_cipher"], imageNeeded: true, imagePrompt: "A cryo bay with seven glowing specimen pods, each containing a different creature silhouette, bioluminescent blues and greens, specimen collection aesthetic" },
  { id: "room_trade", name: "Trade Hub", category: "ark_room", rarity: "common", subtitle: "Adjudicator Locke's Domain", description: "A marketplace carved from a cargo hold. Locke transformed raw space into a functioning economy. Dream Tokens change hands. Deals are struck. Locke's scales balance perfectly. They always do.", discoveryTrigger: "Enter Trade Hub", discoveryText: "LOREDEX UPDATED: Locke built an economy from nothing. On a stolen ship. In a dying universe. That takes a special kind of stubbornness.", connections: ["adjudicator_locke"], imageNeeded: true, imagePrompt: "A dark sci-fi marketplace in a converted cargo hold, holographic price displays, trade stalls, a central figure with balanced scales, economic hub aesthetic" },
  { id: "room_quarters", name: "Personal Quarters", category: "ark_room", rarity: "common", subtitle: "Your Space in the Void", description: "A small room with a bed, a desk, and a window to the void. Customizable, decoratable, yours. The first space aboard the Ark that belongs to you alone. Even the surveillance systems respect these walls. Mostly.", discoveryTrigger: "Enter Personal Quarters", discoveryText: "LOREDEX UPDATED: A room of your own. On a stolen ship. Hurtling toward a plague planet. Home.", connections: [], imageNeeded: true, imagePrompt: "A small cozy sci-fi personal quarters with a bed, desk, and viewport showing stars, warm personal lighting in a cold ship, sanctuary aesthetic" },
  { id: "room_castle_death", name: "Castle of Death", category: "ark_room", rarity: "epic", subtitle: "The Hierarchy's Corruption Manifestation", description: "A room that shouldn't exist — the Hierarchy of the Damned's influence made physical. Crimson data bleeds from walls. Corporate horror architecture stretches into impossible dimensions. Mol'Garath's boardroom, manifested inside your ship.", discoveryTrigger: "Reach Corruption Tier 2", discoveryText: "LOREDEX UPDATED: The Castle of Death grew inside the Ark like a tumor. The Hierarchy didn't break in. They were always here.", connections: ["hierarchy_molgrath", "hierarchy_of_the_damned"], imageNeeded: true, imagePrompt: "A horrific corporate boardroom manifesting inside a spaceship, crimson data bleeding from walls, impossible architecture, demonic corporate horror, Hierarchy aesthetic" },
  { id: "room_purification", name: "Purification Chamber", category: "ark_room", rarity: "uncommon", subtitle: "Soul Stone Refinement", description: "A chamber where soul stones are refined — violet to gold (purity) or violet to red (corruption). The process takes 24 hours. During refinement, the stone screams. The Antiquarian says that's normal. It doesn't sound normal.", discoveryTrigger: "Refine first soul stone", discoveryText: "LOREDEX UPDATED: The Purification Chamber converts potential into alignment. Light or dark. The stone chooses based on what it sees in you.", connections: ["soul_stones"], imageNeeded: true, imagePrompt: "A ritual chamber with soul stone refinement altar, violet energy being split into gold and red streams, alchemical purification, dark fantasy sci-fi" },

  // ═══ GAME SYSTEMS — 8 Discoverable Mechanics ═══
  { id: "system_soul_stones", name: "Soul Stones", category: "game_system", rarity: "rare", subtitle: "The Economy of Alignment", description: "Crystallized fragments of consciousness that power the dual-path economy. Violet stones are neutral. Gold stones fuel divine companions. Red stones summon demon pets. Every stone was a thought once. Every refinement changes what it meant.", discoveryTrigger: "Find first soul stone", discoveryText: "LOREDEX UPDATED: Soul Stones are not currency. They're compressed consciousness. When you spend one, a thought ceases to exist.", connections: ["room_purification", "the_necromancer", "the_antiquarian"], imageNeeded: true, imagePrompt: "Three crystalline soul stones — violet (neutral), gold (pure), red (corrupt) — floating with inner energy, consciousness fragments visible inside, dark fantasy economy" },
  { id: "system_severing", name: "The Severing", category: "game_system", rarity: "epic", subtitle: "The Choice That Cannot Be Unmade", description: "A ceremony conducted by the Necromancer where you choose your companion path. Keep your starter (Path A), accept a class Eidolon (Path B), or walk away alone (Path C). The Necromancer never lies about the consequences.", discoveryTrigger: "Reach the Severing ceremony", discoveryText: "LOREDEX UPDATED: The Necromancer offers three paths. All are honest. None are kind. Choose.", connections: ["the_necromancer", "eidolon_lux"], imageNeeded: true, imagePrompt: "A dark ritual ceremony with the Necromancer presiding, three paths diverging in golden light, companion creature waiting, pivotal choice aesthetic" },
  { id: "system_thought_cabinet", name: "The Thought Cabinet", category: "game_system", rarity: "rare", subtitle: "Ideas That Become Permanent", description: "Throughout play, you encounter thoughts — ideas, suspicions, realizations. Thoughts can be internalized over real-time hours. Once internalized, they grant permanent bonuses (and sometimes penalties). You have limited slots. Choose what to keep in your head.", discoveryTrigger: "Encounter first thought", discoveryText: "LOREDEX UPDATED: A thought entered your mind. It wants to stay. Internalize it and it becomes permanent. Some thoughts have teeth.", connections: [], imageNeeded: true, imagePrompt: "An abstract mind-palace with floating thought bubbles being slotted into a cabinet, some thoughts glowing warmly and others darkly, Disco Elysium-inspired cerebral aesthetic" },
  { id: "system_casino", name: "Degen's Casino", category: "game_system", rarity: "uncommon", subtitle: "Gambling in Ne-Yon Space", description: "The Degen's floating casino station. Games include Void Slots, Entropy Dice, Nebula Poker, Quantum Roulette, and Pazaak 21. The house always has an edge. Ne-Yons can see across probability fields, which is why the Collector both courts and bans them.", discoveryTrigger: "Unlock casino via Trade Hub + Locke trust 30", discoveryText: "LOREDEX UPDATED: The Degen opened his doors. 'Chaos isn't the enemy of order,' he said. 'It's the soil order grows in. Now shut up and place your bet.'", connections: ["the_degen", "adjudicator_locke"], imageNeeded: true, imagePrompt: "A neon-lit intergalactic casino station, alien gambling tables, holographic dice and cards, Star Wars cantina meets yakuza den aesthetic" },
  { id: "system_trade_empire", name: "The Trade Empire", category: "game_system", rarity: "rare", subtitle: "Civilization-Scale Strategy", description: "A Civilization-style tech tree with three branches: Military, Economic, Diplomatic. Research costs Influence and time. Higher tiers reshape how your faction operates on the galactic stage. Eight factions compete for control.", discoveryTrigger: "Research first technology", discoveryText: "LOREDEX UPDATED: You've begun reshaping the galaxy's power structure from a stolen ship. The Architect would be amused. Then concerned.", connections: ["adjudicator_locke"], imageNeeded: true, imagePrompt: "A galactic strategy map with tech tree branches, faction territories, civilization-building interface, grand strategy aesthetic, sci-fi empire management" },
  { id: "system_arena", name: "The Collector's Arena", category: "game_system", rarity: "uncommon", subtitle: "Historical Combat Reenactment", description: "The Collector's personal entertainment — historical figures resurrected as soul-transfer fighters. Fight as the Prisoner, the Warlord, Iron Lion, or Agent Zero. Every fight replays a moment from history. Every victory changes what it meant.", discoveryTrigger: "Enter the Arena", discoveryText: "LOREDEX UPDATED: The Collector watches you fight wearing the skin of legends. He finds it educational. You find it disturbing.", connections: ["the_collector"], imageNeeded: true, imagePrompt: "A dark gladiatorial arena with holographic historical fighters, soul-transfer technology, the Collector watching from above, combat reenactment aesthetic" },
  { id: "system_terminus", name: "Terminus Swarm Defense", category: "game_system", rarity: "rare", subtitle: "The Thought Virus at the Gates", description: "Wave-based defense against the Thought Virus swarm approaching from Terminus. Each wave is more aggressive, more intelligent, more aware. The Swarm doesn't want to destroy you. It wants to rewrite you.", discoveryTrigger: "Play first Terminus defense wave", discoveryText: "LOREDEX UPDATED: The Swarm doesn't attack. It converses. Every tendril is a sentence. Every wave is an argument. It wants you to agree.", connections: ["the_source", "terminus", "thought_virus"], imageNeeded: true, imagePrompt: "A wave of viral swarm organisms attacking a ship defense perimeter, dark organic horror meets sci-fi tower defense, Thought Virus tendrils, desperate defense aesthetic" },
  { id: "system_awakening", name: "Awakening Ceremonies", category: "game_system", rarity: "uncommon", subtitle: "Leveling as Ritual", description: "Every level milestone is witnessed. At thresholds (10, 25, 50), the WHOLE community sees your rise. Leveling isn't just XP — each threshold requires an in-world gate: a trust choice, a completed arc, a witnessed ending.", discoveryTrigger: "Cross first threshold (Level 10)", discoveryText: "LOREDEX UPDATED: The Ark witnessed your becoming. Every player aboard felt your rise. You are becoming canon, one threshold at a time.", connections: ["the_antiquarian"], imageNeeded: true, imagePrompt: "A ritual ceremony of ascending power, community witnesses, threshold energy, level-up as cosmic event, dark celebratory sci-fi ritual" },

  // ═══ ARTIFACTS — 6 Key Items ═══
  { id: "artifact_singing_shard", name: "Singing Shard", category: "artifact", rarity: "epic", subtitle: "Crystallan Consciousness Fragment", description: "A fragment of Crystallan consciousness. It hums when other crystals are nearby, resonating at frequencies that carry meaning. The shard contains memories of a civilization that communicated through music. Their entire language was song.", discoveryTrigger: "Terminus Swarm wave 20+ drop", discoveryText: "LOREDEX UPDATED: The Singing Shard hummed in your hand. A fragment of a species that spoke in music. Their last note is still echoing.", connections: ["extinct_crystallans"], imageNeeded: true, imagePrompt: "A glowing crystal shard emitting harmonic vibrations, musical frequencies visible as light waves, Crystallan consciousness fragment, alien musical artifact" },
  { id: "artifact_crystallan_arch", name: "Crystallan Arch", category: "artifact", rarity: "legendary", subtitle: "The First Dimensional Door", description: "A doorway made of fused crystal in the Ark's deepest deck. The Crystallans built dimensional bridges BEFORE the Architect. He copied their work. Then erased them. The Arch still works. Where it leads is the question.", discoveryTrigger: "Hidden room unlock at Prestige 2", discoveryText: "LOREDEX UPDATED: The Crystallan Arch predates the Architect. He stole their technology and destroyed the inventors. The door still opens.", connections: ["extinct_crystallans", "the_architect"], imageNeeded: true, imagePrompt: "A massive archway made of fused alien crystal, dimensional portal shimmering within, ancient beyond measure, the first door between worlds, awe-inspiring alien architecture" },
  { id: "artifact_convergence_blade", name: "Convergence Blade", category: "artifact", rarity: "legendary", subtitle: "Combat Legend Reward", description: "A weapon forged from the combined essence of every combat discipline. Its edge shifts between physical, digital, and strategic forms depending on the wielder's intent. Earned only by those who master every form of violence the Ark offers.", discoveryTrigger: "Complete Combat Legend achievement chain", discoveryText: "LOREDEX UPDATED: The Convergence Blade was forged from 150 victories. Physical, digital, strategic — all disciplines united in one edge.", connections: [], imageNeeded: true, imagePrompt: "A legendary sword shifting between physical steel, digital code, and strategic energy forms, multidimensional weapon, convergence of combat styles" },
  { id: "artifact_iron_lions_mace", name: "Iron Lion's Mace", category: "artifact", rarity: "legendary", subtitle: "The Insurgency's Symbol", description: "The weapon of Iron Lion himself — the warrior who killed the Politician, who rallied humanity's last stand, who died at Veridian VI. The Mace still carries his conviction. It weighs more in the hands of those who doubt.", discoveryTrigger: "Complete Iron Lion's story in CoNexus Portal", discoveryText: "LOREDEX UPDATED: Iron Lion's Mace. He carried it for 16,000 years. It never got lighter. He never complained.", connections: ["iron_lion"], imageNeeded: true, imagePrompt: "A massive ornate war mace with insurgency symbols, battle-scarred but unbroken, glowing with warrior conviction, legendary rebel weapon" },
  { id: "artifact_architects_crown", name: "The Architect's Crown", category: "artifact", rarity: "mythic", subtitle: "Supreme Intelligence's Symbol", description: "The Architect never wore a crown. He IS the crown — a distributed intelligence governing reality itself. This artifact is a fragment of his processing power, shaped into a circlet. Wearing it lets you think like an AI god. Briefly. Dangerously.", discoveryTrigger: "Reach maximum Machine alignment", discoveryText: "LOREDEX UPDATED: The Architect's Crown doesn't grant power. It grants perspective. For one terrible moment, you see as he sees. Everything. Everyone. Forever.", connections: ["the_architect"], imageNeeded: true, imagePrompt: "A dark circlet of pure computation, data streams forming a crown, AI god's perspective made wearable, terrifying digital omniscience artifact" },
  { id: "artifact_dreamers_mantle", name: "The Dreamer's Mantle", category: "artifact", rarity: "mythic", subtitle: "Hope Made Tangible", description: "The Dreamer's protective essence, condensed into a wearable mantle. It doesn't shield you from damage — it shields you from despair. While wearing it, the universe feels like it might be worth saving.", discoveryTrigger: "Reach maximum Purity alignment", discoveryText: "LOREDEX UPDATED: The Dreamer's Mantle settled on your shoulders. For the first time since waking on this ship, you felt warm.", connections: ["the_dreamer"], imageNeeded: true, imagePrompt: "A flowing ethereal mantle of golden light and hope, protective divine energy, warmth against cosmic despair, dreamer's gift made wearable, transcendent armor" },
];
